def derive_skeleton_key(master_password: str, salt: bytes) -> bytes:
    """Derives a cryptographically secure key from a master password."""
    kdf = PBKDF2HMAC(
        algorithm=hashes.SHA256(),
        length=32,
        salt=salt,
        iterations=600_000, # High iteration count to resist GPU brute-forcing
    )
    return kdf.derive(master_password.encode())

