        self.private_key = ed25519.Ed25519PrivateKey.generate()
        self.public_key = self.private_key.public_key()

    def get_public_bytes(self) -> bytes:
        """Export public identity for mesh registration."""
        return self.public_key.public_bytes(
            encoding=serialization.Encoding.Raw,
            format=serialization.PublicFormat.Raw
        )

    def sign_inference_payload(self, workload_hash: bytes) -> bytes:
        """Sign a workload hash with a timestamp to prevent replay attacks."""
        timestamp = str(int(time.time())).encode()
        payload_to_sign = workload_hash + b"|" + timestamp
        signature = self.private_key.sign(payload_to_sign)
        return signature

