                continue

            # Constraint 2: Memory Ceiling check (Available VRAM must accommodate the task weight)
            if metrics["vram"] < (task_weight_gb + 1.0): # 1GB safety buffer
                continue

            # Optimization: Pick the node meeting constraints with the least cryptographic tax
            if metrics["crypto_load"] < lowest_crypto_impact:
                lowest_crypto_impact = metrics["crypto_load"]
                best_node = node_id

        return best_node

